// errUnsupportedProtocol is the error for a call in a protocol the service lacks.
func errUnsupportedProtocol(rc *request.Context) *awserr.Error {
	return &awserr.Error{
		Code:       "InvalidAction",
		Message:    "The secretsmanager service does not accept this protocol.",
		StatusCode: 400,
		Fault:      awserr.FaultSender,
	}
}

// asError turns what a handler returned into the error that goes on the wire.
func asError(err error) *awserr.Error {
	var ae *awserr.Error
	if errors.As(err, &ae) && ae != nil {
		return ae
	}
	return awserr.Internal(err.Error())
}

// writeError writes err in the error form of the caller's protocol.
func writeError(w http.ResponseWriter, rc *request.Context, err *awserr.Error) {
	switch rc.Protocol {
	case protocol.KindJSON:
		opts := awsjson.ErrorOptions{
			QueryCompatible: awsQueryCompatible,
			ContentType:     "application/x-amz-json-" + jsonVersion,
			MessageName:     messageName(err.Code),
		}
		awsjson.WriteError(w, rc.Request, rc.RequestID, err, opts)
	default:
		http.Error(w, err.Message, err.StatusCode)
	}
}

// messageName is the json name of the message of an error, by its code: the
// name of its shape's message member, where that is not "message".
func messageName(code string) string {
	switch code {
	case "DecryptionFailure":
		return "Message"
	case "EncryptionFailure":
		return "Message"
	case "InternalServiceError":
		return "Message"
	case "InvalidNextTokenException":
		return "Message"
	case "InvalidParameterException":
		return "Message"
	case "InvalidRequestException":
		return "Message"
	case "LimitExceededException":
		return "Message"
	case "MalformedPolicyDocumentException":
		return "Message"
	case "PreconditionNotMetException":
		return "Message"
	case "PublicPolicyException":
		return "Message"
	case "ResourceExistsException":
		return "Message"
	case "ResourceNotFoundException":
		return "Message"
	default:
		return ""
	}
}

func readBody(rc *request.Context) ([]byte, *awserr.Error) {
	body, err := protocol.ReadRequest(rc.Request)
	if errors.Is(err, protocol.ErrBusy) {
		return nil, protocol.ThrottledJSON()
	}
	if err != nil {
		return nil, &awserr.Error{
			Code:       "SerializationException",
			Message:    "The request body could not be read.",
			StatusCode: 400,
			Fault:      awserr.FaultSender,
		}
	}
	if protocol.OverBody(len(body)) {
		return nil, query.MalformedQueryString()
	}
	if !utf8.Valid(body) {
		return nil, errBodyNotUTF8
	}
	return body, nil
}

// decodeJSON reads the json body of a call into a T. A body that only the lenient
// reading takes stays on the request: only that reading clamps an integer past the
// int32 range, and a handler that refuses one echoes the text sent, which only the
// body holds. Any other body is dropped once decoded. A body that would decode into
// more than the call's budget is answered as a body over protocol.MaxBody.
func decodeJSON[T any](rc *request.Context, body []byte) (*T, *awserr.Error) {
	in, lenient, err := awsjson.DecodeWithin[T](body, rc.DecodeBudget(len(body)), rc)
	if err == awsjson.ErrTooLarge {
		return nil, query.MalformedQueryString()
	}
	if lenient {
		rc.Request.Body = io.NopCloser(bytes.NewReader(body))
	}
	return in, err
}

// errBodyNotUTF8 is the answer to a json body that is not valid UTF-8: the same as
// broken json and a lone surrogate escape (awsjson.Decode). LocalStack answers 500
// here, which is a crash in its parser and not an answer to copy.
var errBodyNotUTF8 = &awserr.Error{
	Code:       "SerializationException",
	Message:    "Start of structure or map found where not expected.",
	StatusCode: 400,
	Fault:      awserr.FaultSender,
}

